// Generated by kfx from KFX-0 source: edit that, and regenerate (PLAN.md, section 1).

use kayak_rt::*;
use super::*;

// base.kfx: what the compiler's other files use, first of them all.
//
// The compiler is the files kfx/kfx.unit lists, in order (PLAN.md,
// section 1): to FX-26, one program, each file seeing those before it; to
// Rust, a module each. Fixpt runs them, after kfx/prelude.fx, to make
// boot/src/kfx/ (stage 0); the Rust built from that runs them again, and
// must make the same files.
//
// `compile` (compile.kfx) takes a program's text and gives its Rust: it
// reads the text into `sexp`s (read.kfx), checks it (check.kfx), and
// writes Rust (emit.kfx) onto a list of characters, newest first, which is
// reversed once at the end.

pub type Chars = List<char>;

pub type Strings = List<Str>;

// Lists, of anything
pub fn map<A: Copy + 'static, B: Copy + 'static>(f: &'static (dyn Fn(A) -> B + Send + Sync), xs: List<A>) -> List<B> {
    if null_p(xs) {
        nil::<B>()
    } else {
        kayak_rt::heap_cons(f(car(xs)), map(f, cdr(xs)))
    }
}

pub fn any_p<A: Copy + 'static>(p: &'static (dyn Fn(A) -> bool + Send + Sync), xs: List<A>) -> bool {
    (not(null_p(xs)) && (p(car(xs)) || any_p(p, cdr(xs))))
}

pub fn filter<A: Copy + 'static>(mut p: &'static (dyn Fn(A) -> bool + Send + Sync), mut xs: List<A>) -> List<A> {
    loop {
        if null_p(xs) {
            return nil::<A>();
        } else if p(car(xs)) {
            return kayak_rt::heap_cons(car(xs), filter(p, cdr(xs)));
        } else {
            xs = cdr(xs);
            continue;
        }
    }
}

pub fn map2<A: Copy + 'static, B: Copy + 'static, C: Copy + 'static>(f: &'static (dyn Fn(A, B) -> C + Send + Sync), xs: List<A>, ys: List<B>) -> List<C> {
    if (null_p(xs) || null_p(ys)) {
        nil::<C>()
    } else {
        kayak_rt::heap_cons(f(car(xs), car(ys)), map2(f, cdr(xs), cdr(ys)))
    }
}

pub fn size_from<A: Copy + 'static>(mut xs: List<A>, mut n: i64) -> i64 {
    loop {
        if null_p(xs) {
            return n;
        } else {
            (xs, n) = (cdr(xs), i64_plus(n, 1i64));
            continue;
        }
    }
}

pub fn size<A: Copy + 'static>(xs: List<A>) -> i64 {
    size_from(xs, 0i64)
}

pub fn last<A: Copy + 'static>(mut xs: List<A>) -> A {
    loop {
        if null_p(cdr(xs)) {
            return car(xs);
        } else {
            xs = cdr(xs);
            continue;
        }
    }
}

pub fn onto<A: Copy + 'static>(xs: List<A>, ys: List<A>) -> List<A> {
    if null_p(xs) {
        ys
    } else {
        kayak_rt::heap_cons(car(xs), onto(cdr(xs), ys))
    }
}

pub fn concat<A: Copy + 'static>(xss: List<List<A>>) -> List<A> {
    if null_p(xss) {
        nil::<A>()
    } else {
        onto(car(xss), concat(cdr(xss)))
    }
}

// Characters and strings
pub fn rev_onto(mut xs: Chars, mut acc: Chars) -> Chars {
    loop {
        if null_p(xs) {
            return acc;
        } else {
            (xs, acc) = (cdr(xs), kayak_rt::heap_cons(car(xs), acc));
            continue;
        }
    }
}

pub fn rev_to_string(acc: Chars) -> Str {
    list_to_string(rev_onto(acc, nil::<char>()))
}

/// A string's characters, in one pass: indexing a string that is not
/// ASCII counts characters from its start (CLAUDES_CHOICES.md, C14).
pub fn string_chars(s: Str) -> Chars {
    string_to_list(s)
}

// Strings `xs` joined, in order (C261): adjacent ones appended pairwise,
// again and again, each round halving the list, so each character is
// copied once a round, some log2(n) times; where appending each onto the
// rest copies the rest again for each, n times. FX-26 has it as
// `(apply string-append xs)`, which KFX has not (C71); in KFX, so that it
// is the same on every engine.
pub fn string_pairs(xs: Strings) -> Strings {
    if (null_p(xs) || null_p(cdr(xs))) {
        xs
    } else {
        kayak_rt::heap_cons(string_append(car(xs), car(cdr(xs))), string_pairs(cdr(cdr(xs))))
    }
}

pub fn string_list_append(mut xs: Strings) -> Str {
    loop {
        if null_p(xs) {
            return str_lit("");
        } else if null_p(cdr(xs)) {
            return car(xs);
        } else {
            xs = string_pairs(xs);
            continue;
        }
    }
}

pub fn put_from(mut s: Str, mut i: i64, mut n: i64, mut acc: Chars) -> Chars {
    loop {
        if i64_lt(i, n) {
            (i, acc) = (i64_plus(i, 1i64), kayak_rt::heap_cons(string_ref_i64(s, i), acc));
            continue;
        } else {
            return acc;
        }
    }
}

/// Adds `s` to the output `acc`.
pub fn put(s: Str, acc: Chars) -> Chars {
    put_from(s, 0i64, string_length_i64(s), acc)
}

/// Each of `xs` added to `acc` by `each`, separated by `sep`.
pub fn put_sep<A: Copy + 'static>(mut each: &'static (dyn Fn(A, Chars) -> Chars + Send + Sync), mut sep: Str, mut xs: List<A>, mut acc: Chars) -> Chars {
    loop {
        if null_p(xs) {
            return acc;
        } else if null_p(cdr(xs)) {
            return each(car(xs), acc);
        } else {
            (xs, acc) = (cdr(xs), put(sep, each(car(xs), acc)));
            continue;
        }
    }
}

pub fn string_member_p(s: Str, xs: Strings) -> bool {
    if null_p(xs) {
        false
    } else {
        (string_eq_p(s, car(xs)) || string_member_p(s, cdr(xs)))
    }
}

/// `from`, `from` + 1, ..., to before `n` (C91: from terminate.kfx, which
/// the emitter used too, now a module of its own).
pub fn counting(from: i64, n: i64) -> List<i64> {
    if i64_lt(from, n) {
        kayak_rt::heap_cons(from, counting(i64_plus(from, 1i64), n))
    } else {
        nil::<i64>()
    }
}

// A set of names, a balanced tree (C92): a membership test in a few
// comparisons, where a list of hundreds took as many.
pub enum Nset {
    Nempty(),
    Nnode(&'static Nset, Str, &'static Nset),
}

pub fn nempty() -> &'static Nset {
    kayak_rt::heap_alloc(Nset::Nempty())
}

pub fn nnode(f0: &'static Nset, f1: Str, f2: &'static Nset) -> &'static Nset {
    kayak_rt::heap_alloc(Nset::Nnode(f0, f1, f2))
}

pub fn merged_strings(a: List<Str>, b: List<Str>) -> List<Str> {
    if null_p(a) {
        b
    } else if null_p(b) {
        a
    } else if string_lt_p(car(b), car(a)) {
        kayak_rt::heap_cons(car(b), merged_strings(a, cdr(b)))
    } else {
        kayak_rt::heap_cons(car(a), merged_strings(cdr(a), b))
    }
}

pub fn sorted_strings(xs: List<Str>) -> List<Str> {
    if (null_p(xs) || null_p(cdr(xs))) {
        xs
    } else {
        merged_strings(sorted_strings(halves(xs, true)), sorted_strings(halves(xs, false)))
    }
}

/// Every other element, the first's or the second's.
pub fn halves(mut xs: List<Str>, mut first: bool) -> List<Str> {
    loop {
        if null_p(xs) {
            return nil::<Str>();
        } else if first {
            return kayak_rt::heap_cons(car(xs), halves(cdr(xs), false));
        } else {
            (xs, first) = (cdr(xs), true);
            continue;
        }
    }
}

pub fn taken(xs: List<Str>, n: i64) -> List<Str> {
    if (null_p(xs) || i64_lt_eq(n, 0i64)) {
        nil::<Str>()
    } else {
        kayak_rt::heap_cons(car(xs), taken(cdr(xs), i64_minus(n, 1i64)))
    }
}

pub fn dropped(mut xs: List<Str>, mut n: i64) -> List<Str> {
    loop {
        if (null_p(xs) || i64_lt_eq(n, 0i64)) {
            return xs;
        } else {
            (xs, n) = (cdr(xs), i64_minus(n, 1i64));
            continue;
        }
    }
}

/// The first `n` of `xs`, sorted, as a balanced tree.
pub fn tree_of(xs: List<Str>, n: i64) -> &'static Nset {
    if i64_lt_eq(n, 0i64) {
        nempty()
    } else {
        let half = i64_quotient(n, 2i64);
        let rest = dropped(xs, half);
        nnode(tree_of(xs, half), car(rest), tree_of(cdr(rest), i64_minus(i64_minus(n, half), 1i64)))
    }
}

pub fn nset_of(xs: List<Str>) -> &'static Nset {
    let sorted = sorted_strings(xs);
    tree_of(sorted, size(sorted))
}

/// `s` with `x`, unbalanced: for what a walk has seen.
pub fn nset_added(x: Str, s: &'static Nset) -> &'static Nset {
    let tagcase_ = s;
    match *tagcase_ {
        Nset::Nempty() => {
            nnode(nempty(), x, nempty())
        }
        Nset::Nnode(l, k, r) => {
            if string_eq_p(x, k) {
                s
            } else if string_lt_p(x, k) {
                nnode(nset_added(x, l), k, r)
            } else {
                nnode(l, k, nset_added(x, r))
            }
        }
    }
}

pub fn in_nset_p(mut x: Str, mut s: &'static Nset) -> bool {
    loop {
        let tagcase_ = s;
        match *tagcase_ {
            Nset::Nempty() => {
                return false;
            }
            Nset::Nnode(l, k, r) => {
                if string_eq_p(x, k) {
                    return true;
                } else if string_lt_p(x, k) {
                    s = l;
                    continue;
                } else {
                    s = r;
                    continue;
                }
            }
        }
    }
}

